177	    char sel_hdr[32];
178	    snprintf(host_hdr, sizeof(host_hdr), "x-gerrit-host-%s", MCP_GERRIT_SEG);
179	    snprintf(sel_hdr, sizeof(sel_hdr), "x-gerrit-%s", MCP_GERRIT_SEG);
180	
181	    headers[h].name = "Accept";
182	    headers[h].value = "application/json, text/event-stream";
183	    h++;
184	
185	    /* Force new connection each request — some MCP servers (e.g. DiDi)
186	     * close the connection after responding, but vela_tls pool tries to
187	     * reuse it and hangs on read. */
188	    headers[h].name = "Connection";
189	    headers[h].value = "close";
190	    h++;
191	
192	    if (srv->session_id[0]) {
193	        headers[h].name = "Mcp-Session";
194	        headers[h].value = srv->session_id;
195	        h++;
196	    }
