201	         * "x-user-token", NOT a standard "************** ****** <token>".
202	         * srv->token outlives the post call (caller holds the lock or a
203	         * stack copy of the server struct), so no heap buffer is needed. */
204	        headers[h].name = "x-user-token";
205	        headers[h].value = srv->token;
